// Bundle report (G37.9, 3.5.11): what the first page load fetches and what every lazy chunk holds.
// Reads vite's manifest and the source maps of `dist/`. Usage, after `vite build`:
//   node packages/web/scripts/bundle-report.mjs [out.json]   (BUNDLE_FILES=1: our files one by one)
// Sizes are raw and gzip; a chunk's packages come from its source map (generated bytes per
// source, scaled to the chunk's real size).
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { gzipSync } from "node:zlib";

const dist = fileURLToPath(new URL("../dist", import.meta.url));
const manifest = JSON.parse(readFileSync(join(dist, ".vite", "manifest.json"), "utf8"));

const size = (file) => {
  const buf = readFileSync(join(dist, file));
  return { raw: buf.length, gzip: gzipSync(buf, { level: 9 }).length };
};

/** The package a source path belongs to ("src" for our own code). */
function packageOf(source) {
  // BUNDLE_FILES=1: our own files one by one, to see which components a chunk holds.
  if (process.env.BUNDLE_FILES && source.includes("/src/"))
    return source.replace(/^.*\/src\//, "src/");
  const m = source.match(/node_modules\/(?:\.pnpm\/[^/]+\/node_modules\/)?((?:@[^/]+\/)?[^/]+)/);
  if (m) return m[1];
  return source.includes("/src/") ? "src" : "other";
}

const B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

/** Generated bytes per source, from the map's VLQ mappings (what the chunk really holds). */
function packagesIn(file) {
  let map;
  let code;
  try {
    map = JSON.parse(readFileSync(join(dist, `${file}.map`), "utf8"));
    code = readFileSync(join(dist, file), "utf8").split("\n");
  } catch {
    return { by: new Map(), total: 0 };
  }
  const by = new Map();
  let total = 0;
  let src = 0;
  const lines = map.mappings.split(";");
  lines.forEach((line, li) => {
    const segs = [];
    let col = 0;
    for (const seg of line.split(",")) {
      if (!seg) continue;
      const vals = [];
      let v = 0;
      let shift = 0;
      for (const ch of seg) {
        const d = B64.indexOf(ch);
        v += (d & 31) << shift;
        if (d & 32) shift += 5;
        else {
          vals.push(v & 1 ? -(v >>> 1) : v >>> 1);
          v = 0;
          shift = 0;
        }
      }
      col += vals[0];
      if (vals.length > 1) src += vals[1];
      segs.push([col, vals.length > 1 ? src : -1]);
      // The other fields (line, column, name) are not needed here.
    }
    const len = code[li]?.length ?? 0;
    segs.forEach(([c, s], i) => {
      const n = (i + 1 < segs.length ? segs[i + 1][0] : len) - c;
      if (s < 0 || n <= 0) return;
      const p = packageOf(map.sources[s]);
      by.set(p, (by.get(p) ?? 0) + n);
      total += n;
    });
  });
  return { by, total };
}

const entryKey = Object.keys(manifest).find((k) => manifest[k].isEntry);
// Everything the browser fetches before the first paint: the entry and its static imports.
const initial = new Set();
const walk = (key) => {
  if (initial.has(key)) return;
  initial.add(key);
  for (const k of manifest[key].imports ?? []) walk(k);
};
walk(entryKey);

const chunks = Object.entries(manifest)
  .filter(([, c]) => c.file.endsWith(".js") || c.file.endsWith(".mjs"))
  .map(([key, c]) => {
    const s = size(c.file);
    const { by, total } = packagesIn(c.file);
    const top = [...by.entries()]
      .sort((a, b) => b[1] - a[1])
      .slice(0, Number(process.env.BUNDLE_TOP ?? 6))
      .map(([name, n]) => ({ name, raw: total ? Math.round((n / total) * s.raw) : 0 }));
    return { key, file: c.file, initial: initial.has(key), ...s, top };
  })
  .sort((a, b) => b.raw - a.raw);

const css = [...initial].flatMap((k) => manifest[k].css ?? []);
const cssSize = [...new Set(css)].reduce(
  (acc, f) => {
    const s = size(f);
    return { raw: acc.raw + s.raw, gzip: acc.gzip + s.gzip };
  },
  { raw: 0, gzip: 0 },
);
const first = chunks.filter((c) => c.initial);
const sum = (list, k) => list.reduce((a, c) => a + c[k], 0);
const report = {
  entry: manifest[entryKey].file,
  initialJs: { raw: sum(first, "raw"), gzip: sum(first, "gzip"), chunks: first.length },
  initialCss: cssSize,
  allJs: { raw: sum(chunks, "raw"), gzip: sum(chunks, "gzip"), chunks: chunks.length },
  chunks,
};

const kb = (n) => `${(n / 1024).toFixed(1)} KB`;
console.log(
  `first load: JS ${kb(report.initialJs.raw)} (gzip ${kb(report.initialJs.gzip)}) in ${first.length} chunks, CSS ${kb(cssSize.raw)} (gzip ${kb(cssSize.gzip)})`,
);
for (const c of first)
  console.log(
    `  ${c.file.padEnd(48)} ${kb(c.raw).padStart(10)} ${kb(c.gzip).padStart(10)}  ${c.top
      .map((t) => `${t.name} ${kb(t.raw)}`)
      .join(", ")}`,
  );
console.log("largest lazy chunks:");
for (const c of chunks.filter((c) => !c.initial).slice(0, 25))
  console.log(
    `  ${c.file.padEnd(48)} ${kb(c.raw).padStart(10)} ${kb(c.gzip).padStart(10)}  ${c.top
      .slice(0, 3)
      .map((t) => `${t.name} ${kb(t.raw)}`)
      .join(", ")}`,
  );
if (process.argv[2]) writeFileSync(process.argv[2], JSON.stringify(report, null, 2));
